INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020014, "", 302, 91, "", "", "", "", "", "", 13020011);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020015, "", 302, 11, "いかんいかん\n資材の山に埋もれて\nしまうところだった", 10, "", "", "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020016, "", 302, 91, "", "", "", "", "", "", 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020017, "", 302, 3, "nyx_302_yuni_02", 0, 1, 0.2, "NoItem", "", 2);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020018, "", 302, 3, "nyx_302_yuni_02", 0, 1, 0.2, "nyx_idle_normal", 0.2, 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020019, "", 302, 11, "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", 10, "", "", "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020020, "", 302, 93, "", "", "", "", "", "", 5);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020021, "", 302, 4, 0, "", "", "", "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020022, "", 302, 3, "nyx_cmn_03", 1, "", 0.2, "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020023, "", 302, 11, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 10, "", "", "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020024, "", 302, 91, "", "", "", "", "", "", 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020025, "", 302, 3, "nyx_301_yuni_01", 1, "", 0.2, "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020026, "", 302, 11, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 10, "", "", "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020027, "", 302, 91, 1, "", "", "", "", "", 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020028, "", 302, 11, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 10, "", "", "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020029, "", 302, 91, 1, "", "", "", "", "", 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020030, "", 302, 3, "nyx_302_yuni_03", 0, 1, 0.2, "nyx_302_yuni_04", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020031, "", 302, 11, "是非もなし\nいざ往かん！", 10, "", "", "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020032, "", 302, 91, 1, "", "", "", "", "", 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020033, "", 302, 93, "", "", "", "", "", "", 1.5);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020034, "", 302, 11, "む。奥に入りすぎた\nこれは…出られぬ！\n誰かー！　誰か―！", 10, "", "", "", "", 111031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020035, "", 302, 91, "", "", "", "", "", "", 0);
